import { Sprite, Text } from 'pixi.js';
import gsap from 'gsap';

import { AssetManager } from '@game-studio/asset-manager';
import { Device } from '@game-studio/device';

import { ICabinetConfig, IRequiredStrings } from '../../types/cabinet';
import { messageTextStyle, messageTextStyleRegular } from '../../layout/text-style';
import { SharedMessageView } from './shared-message-view';

export class BalanceView extends SharedMessageView {
    private balanceLabel: Text;
    private icon: Sprite;
    private strings: IRequiredStrings;
    private xGap: number = 20;
    private iconGap: number = 8;
    private shouldUpdateIcon: boolean = false;
    private iconTextureName: string | null = null;
    private textYPosition: number = 0;

    protected get tweenTargets(): gsap.TweenTarget[] { return [this.textContainer]; }
    protected get maskWidth(): number { return this.isLeftHanded ? -this.maxDimensions.width : this.maxDimensions.width; }
    protected get animateOnTargetY(): number { return this.textYPosition; }

    constructor(device: Device, strings: IRequiredStrings) {
        super(device);

        this.strings = strings;

        this.createText();
        this.createIcon();

        this.name = 'balance-view';
    }

    /** Flags the icon as needing to be changed on the next setText() call */
    public setIcon(textureName: string | null): void {
        if (textureName === null) {
            if (this.icon.renderable) {
                this.shouldUpdateIcon = true;
                this.iconTextureName = null;
            }
        } else {
            if (!this.icon.renderable || this.iconTextureName !== textureName) {
                this.shouldUpdateIcon = true;
                this.iconTextureName = textureName;
            }
        }
    }

    protected override updateText(text: string): void {
        if (this.shouldUpdateIcon) {
            this.icon.renderable = this.iconTextureName !== null;
            this.balanceLabel.renderable = !this.icon.renderable;

            if (this.iconTextureName) {
                this.icon.texture = AssetManager.getTexture(this.iconTextureName);
            }

            this.shouldUpdateIcon = false;
        }

        super.updateText(text);
    }

    public override updateTextStyle(config: ICabinetConfig): void {
        super.updateTextStyle(config);

        this.balanceLabel.style = this.isMobilePortrait ? messageTextStyle : messageTextStyleRegular;
    }

    public override updateLayoutStyle(): void {
        super.updateLayoutStyle();
        this.balanceLabel.style.fontFamily = 'Wallop-Bold';
    }

    protected override createText(): void {
        super.createText();

        this.balanceLabel = new Text(this.strings.balanceHeader, messageTextStyle);
        this.balanceLabel.anchor.set(0, 0.5);
        this.balanceLabel.name = 'balance-view-label';

        this.messageText.anchor.set(0, 0.5);
        this.messageText.name = 'balance-view-text';

        this.textContainer.addChild(this.balanceLabel);
    }

    protected updateMessageScale(): void {
        if (!this.balanceLabel || !this.messageText) { return; }
        if (this.maxDimensions.width === 0 || this.maxDimensions.height === 0) { return; }

        if (this.icon.renderable) {
            this.positionAndScaleIcon();
        } else {
            this.positionAndScaleText();
        }
    }

    protected scaleTextToRatio(text: Text, heightRatio: number): void {
        const widthScale = this.maxDimensions.width / text.width;
        const heightScale = (this.maxDimensions.height * heightRatio) / text.height;
        const scale = Math.min(widthScale, heightScale, SharedMessageView.MAX_SCALE);
        text.scale.set(scale);
    }

    private positionAndScaleText(): void {
        this.balanceLabel.scale.set(1);
        this.messageText.scale.set(1);

        if (this.isMobilePortrait) {
            this.balanceLabel.anchor.set(this.isLeftHanded ? 1 : 0, 0);
            this.messageText.anchor.set(this.isLeftHanded ? 1 : 0, 0);

            const labelHeightRatio = 0.33;
            const messageHeightRatio = 1 - labelHeightRatio;
            this.scaleTextToRatio(this.balanceLabel, labelHeightRatio);
            this.scaleTextToRatio(this.messageText, messageHeightRatio);

            this.textYPosition = (this.maxDimensions.height - (this.balanceLabel.height + this.messageText.height)) * 0.5;
            this.balanceLabel.position.set(0, 0);
            this.messageText.position.set(0, this.balanceLabel.height);
            this.textContainer.position.set(0, this.textYPosition);
        } else {
            this.balanceLabel.anchor.set(this.isLeftHanded ? 1 : 0, 0.5);
            this.messageText.anchor.set(this.isLeftHanded ? 1 : 0, 0.5);

            const totalWidth = this.balanceLabel.width + this.messageText.width + this.xGap;
            const maxHeight = Math.max(this.balanceLabel.height, this.messageText.height);

            const scale = this.calculateTextScale(totalWidth, maxHeight);
            const scaledGap = this.xGap * scale;

            this.balanceLabel.scale.set(scale);
            this.messageText.scale.set(scale);

            this.textYPosition = this.maxDimensions.height * 0.5;
            this.textContainer.position.set(0, this.textYPosition);
            if (this.isLeftHanded) {
                this.messageText.position.set(0, 0);
                this.balanceLabel.position.set(-this.messageText.width - scaledGap, 0);
            } else {
                this.balanceLabel.position.set(0, 0);
                this.messageText.position.set(this.balanceLabel.width + scaledGap, 0);
            }
        }
    }

    private createIcon(): void {
        this.icon = new Sprite();
        this.icon.anchor.set(0.5);
        this.icon.renderable = false;

        this.textContainer.addChild(this.icon);
    }

    private positionAndScaleIcon(): void {
        if (!this.icon.texture || this.icon.texture.width === 0) { return; }

        // Reset scales to calculate natural sizes
        this.icon.scale.set(1);
        this.messageText.scale.set(1);

        // Scale icon to match text height
        const iconBaseScale = this.messageText.height / this.icon.height;
        this.icon.scale.set(iconBaseScale);

        // Calculate total width needed and max height
        const totalWidth = this.icon.width + this.messageText.width + this.iconGap;
        const maxHeight = Math.max(this.icon.height, this.messageText.height);

        // Calculate scale to fit within bounds
        const scale = this.calculateTextScale(totalWidth, maxHeight);

        const scaledGap = this.iconGap * scale;

        // Apply final scales
        this.icon.scale.set(iconBaseScale * scale);
        this.messageText.scale.set(scale);

        // Position side by side (same for portrait and landscape)
        this.icon.anchor.set(this.isLeftHanded ? 1 : 0, 0.5);
        this.messageText.anchor.set(this.isLeftHanded ? 1 : 0, 0.5);

        this.textYPosition = this.maxDimensions.height * 0.5;
        this.textContainer.position.set(0, this.textYPosition);

        if (this.isLeftHanded) {
            this.messageText.position.set(0, 0);
            this.icon.position.set(-this.messageText.width - scaledGap, 0);
        } else {
            this.icon.position.set(0, 0);
            this.messageText.position.set(this.icon.width + scaledGap, 0);
        }
    }
}